&lt;p data-pm-slice=&quot;1 1 [&amp;quot;bullet_list&amp;quot;,{&amp;quot;tight&amp;quot;:false},&amp;quot;list_item&amp;quot;,{&amp;quot;style&amp;quot;:&amp;quot;color:#000000 !important;&amp;quot;}]&quot;&gt;This posting is for an existing vacancy.&lt;/p&gt;
